-- Condition details 2026-11-23: what each condition is, its symptoms, what causes it or raises the risk, when to book a visit and when to get
-- help now. General information written from the sources each condition already cites (NHS, WHO and guideline pages); it names no
-- medicine dose and is not a diagnosis. Written by an editor, not yet reviewed by a medical reviewer: ask for the review before relying on it.
-- A line with no source of its own uses the condition's sources. Lines can be changed in the admin (PUT /api/v1/admin/conditions/{slug}/details).
INSERT INTO condition_details (condition_id, kind, sort, text)
SELECT c.id, v.kind, v.sort, jsonb_build_object('en', v.en, 'bn', v.bn)
FROM (VALUES
  ('diabetes', 'about', 0, 'Type 2 diabetes is a long-term condition in which the body does not use insulin well, so blood sugar stays too high. Food, activity and weight all affect it.', 'টাইপ ২ ডায়াবেটিস দীর্ঘমেয়াদি অবস্থা, যাতে শরীর ইনসুলিন ভালোভাবে কাজে লাগাতে পারে না, ফলে রক্তে শর্করা বেশি থাকে। খাবার, শরীরচর্চা ও ওজন এর ওপর প্রভাব ফেলে।'),
  ('diabetes', 'symptoms', 0, 'Passing urine more often than usual, especially at night', 'স্বাভাবিকের চেয়ে বেশি প্রস্রাব হওয়া, বিশেষ করে রাতে'),
  ('diabetes', 'symptoms', 1, 'Feeling thirsty all the time', 'সারাক্ষণ পিপাসা লাগা'),
  ('diabetes', 'symptoms', 2, 'Feeling very tired', 'খুব ক্লান্ত লাগা'),
  ('diabetes', 'symptoms', 3, 'Losing weight without trying', 'চেষ্টা ছাড়াই ওজন কমে যাওয়া'),
  ('diabetes', 'symptoms', 4, 'Cuts and sores that heal slowly, or repeated skin and genital infections', 'কাটা-ছেঁড়া দেরিতে সারা, বা বারবার চামড়ায় ও গোপনাঙ্গে সংক্রমণ'),
  ('diabetes', 'symptoms', 5, 'Blurred vision', 'ঝাপসা দেখা'),
  ('diabetes', 'symptoms', 6, 'Many people have no symptoms at first, so a blood test is the only way to know', 'অনেকের শুরুতে কোনো লক্ষণ থাকে না, তাই রক্ত পরীক্ষাই জানার একমাত্র উপায়'),
  ('diabetes', 'causes', 0, 'Being overweight, especially extra fat around the waist', 'ওজন বেশি হওয়া, বিশেষ করে কোমরের চারপাশে বাড়তি চর্বি'),
  ('diabetes', 'causes', 1, 'A parent, brother or sister with diabetes', 'বাবা-মা বা ভাইবোনের ডায়াবেটিস থাকা'),
  ('diabetes', 'causes', 2, 'Getting older; South Asian people can be affected younger and at a lower weight', 'বয়স বাড়া; দক্ষিণ এশীয়দের কম বয়সে ও কম ওজনেও হতে পারে'),
  ('diabetes', 'causes', 3, 'Little physical activity, and high blood pressure', 'শারীরিক পরিশ্রম কম হওয়া এবং উচ্চ রক্তচাপ'),
  ('diabetes', 'see_doctor', 0, 'Any of the symptoms above, even if mild', 'ওপরের যেকোনো লক্ষণ, হালকা হলেও'),
  ('diabetes', 'see_doctor', 1, 'A close relative with diabetes and you have never had a blood sugar test', 'কাছের আত্মীয়ের ডায়াবেটিস আছে অথচ আপনি কখনো রক্তে শর্করা পরীক্ষা করেননি'),
  ('diabetes', 'see_doctor', 2, 'If you take diabetes medicine: shakiness, sweating or confusion that keeps coming back', 'ডায়াবেটিসের ওষুধ খেলে: কাঁপুনি, ঘাম বা বিভ্রান্তি বারবার হওয়া'),
  ('diabetes', 'urgent', 0, 'Very thirsty with vomiting, stomach pain, fast breathing or fruity-smelling breath', 'প্রচণ্ড পিপাসার সঙ্গে বমি, পেটে ব্যথা, দ্রুত শ্বাস বা ফলের মতো গন্ধের নিঃশ্বাস'),
  ('diabetes', 'urgent', 1, 'Confusion, fainting or a fit', 'বিভ্রান্তি, অজ্ঞান হয়ে যাওয়া বা খিঁচুনি'),
  ('fatty-liver', 'about', 0, 'Fatty liver means extra fat builds up in the liver in a person who drinks little or no alcohol. It is common, usually quiet at first, and often linked to weight and blood sugar.', 'ফ্যাটি লিভারে যিনি কম বা একদমই মদ্যপান করেন না, তাঁরও লিভারে বাড়তি চর্বি জমে। এটি সাধারণ, শুরুতে প্রায় নীরব থাকে এবং ওজন ও রক্তের শর্করার সঙ্গে জড়িত।'),
  ('fatty-liver', 'symptoms', 0, 'Usually no symptoms for years', 'বছরের পর বছর সাধারণত কোনো লক্ষণ থাকে না'),
  ('fatty-liver', 'symptoms', 1, 'Tiredness', 'ক্লান্তি'),
  ('fatty-liver', 'symptoms', 2, 'A dull ache or fullness in the upper right of the tummy', 'পেটের ওপরের ডান দিকে ভোঁতা ব্যথা বা ভারী ভাব'),
  ('fatty-liver', 'symptoms', 3, 'Later, if the liver is badly damaged: yellow skin or eyes, itchy skin, swollen legs or tummy', 'পরে লিভার বেশি ক্ষতিগ্রস্ত হলে: ত্বক বা চোখ হলুদ, চামড়া চুলকানো, পা বা পেট ফোলা'),
  ('fatty-liver', 'causes', 0, 'Being overweight, especially fat around the belly', 'ওজন বেশি, বিশেষ করে পেটের চর্বি'),
  ('fatty-liver', 'causes', 1, 'Type 2 diabetes or raised blood sugar', 'টাইপ ২ ডায়াবেটিস বা রক্তে শর্করা বেশি'),
  ('fatty-liver', 'causes', 2, 'High cholesterol or triglycerides, and high blood pressure', 'উচ্চ কোলেস্টেরল বা ট্রাইগ্লিসারাইড এবং উচ্চ রক্তচাপ'),
  ('fatty-liver', 'causes', 3, 'Very fast weight loss, and a lot of sugary drinks and fried food', 'খুব দ্রুত ওজন কমানো এবং প্রচুর মিষ্টি পানীয় ও ভাজাপোড়া'),
  ('fatty-liver', 'see_doctor', 0, 'Ongoing tiredness or an ache in the upper right tummy', 'দীর্ঘদিন ক্লান্তি বা পেটের ওপরের ডান দিকে ব্যথা'),
  ('fatty-liver', 'see_doctor', 1, 'Diabetes, high cholesterol or a big waist with no liver check yet: ask for a blood test or scan', 'ডায়াবেটিস, উচ্চ কোলেস্টেরল বা মোটা কোমর থাকলে এবং লিভার পরীক্ষা না হয়ে থাকলে: রক্ত পরীক্ষা বা স্ক্যান চান'),
  ('fatty-liver', 'urgent', 0, 'Yellow skin or eyes together with confusion or drowsiness', 'ত্বক বা চোখ হলুদের সঙ্গে বিভ্রান্তি বা ঘুমঘুম ভাব'),
  ('fatty-liver', 'urgent', 1, 'Vomiting blood, or black sticky stools', 'রক্তবমি, বা কালো আঠালো পায়খানা'),
  ('asthma', 'about', 0, 'Asthma is a long-term condition in which the airways become sore and narrow, making breathing hard. It comes and goes, and most people control it with the right plan.', 'অ্যাজমা দীর্ঘমেয়াদি অবস্থা, যাতে শ্বাসনালি ফুলে সরু হয়ে যায় ও শ্বাস নিতে কষ্ট হয়। এটি আসে-যায়, আর সঠিক পরিকল্পনায় বেশির ভাগ মানুষ একে নিয়ন্ত্রণে রাখেন।'),
  ('asthma', 'symptoms', 0, 'Wheezing: a whistling sound when breathing out', 'সাঁই সাঁই শব্দ: শ্বাস ছাড়ার সময় শিসের মতো আওয়াজ'),
  ('asthma', 'symptoms', 1, 'Shortness of breath', 'শ্বাসকষ্ট'),
  ('asthma', 'symptoms', 2, 'A tight chest', 'বুক চেপে ধরা ভাব'),
  ('asthma', 'symptoms', 3, 'Coughing, often worse at night, early morning, in cold air or with exercise', 'কাশি, প্রায়ই রাতে, ভোরে, ঠান্ডা বাতাসে বা পরিশ্রমে বেড়ে যায়'),
  ('asthma', 'causes', 0, 'Triggers: dust mites, pollen, mould, pets, smoke and strong smells', 'উসকানি: ধুলোর মাইট, পরাগ, ছত্রাক, পোষা প্রাণী, ধোঁয়া ও তীব্র গন্ধ'),
  ('asthma', 'causes', 1, 'Cold air, exercise and chest infections such as colds', 'ঠান্ডা বাতাস, পরিশ্রম এবং সর্দির মতো বুকের সংক্রমণ'),
  ('asthma', 'causes', 2, 'Asthma, eczema or allergies in the family', 'পরিবারে অ্যাজমা, একজিমা বা অ্যালার্জি থাকা'),
  ('asthma', 'causes', 3, 'Some people notice certain foods make it worse; keep a note and tell your doctor', 'কারও কারও কিছু খাবারে বাড়ে; লিখে রাখুন ও ডাক্তারকে জানান'),
  ('asthma', 'see_doctor', 0, 'Cough, wheeze or breathlessness that keeps coming back', 'কাশি, সাঁই সাঁই শব্দ বা শ্বাসকষ্ট বারবার হওয়া'),
  ('asthma', 'see_doctor', 1, 'Needing your reliever more often, or waking at night with symptoms', 'রিলিভার বেশি লাগা, বা রাতে লক্ষণে ঘুম ভাঙা'),
  ('asthma', 'see_doctor', 2, 'Having no written asthma action plan', 'লিখিত অ্যাজমা অ্যাকশন প্ল্যান না থাকা'),
  ('asthma', 'urgent', 0, 'Your reliever is not helping, or you cannot speak a full sentence', 'রিলিভারে কাজ হচ্ছে না, বা পুরো বাক্য বলতে পারছেন না'),
  ('asthma', 'urgent', 1, 'Blue or grey lips or fingertips, or very fast breathing', 'ঠোঁট বা আঙুলের ডগা নীল বা ধূসর, বা খুব দ্রুত শ্বাস'),
  ('migraine', 'about', 0, 'Migraine is a headache condition with attacks that can last from a few hours to a few days. It is more than a bad headache, and attacks often have personal triggers.', 'মাইগ্রেন একধরনের মাথাব্যথার অবস্থা, যার আক্রমণ কয়েক ঘণ্টা থেকে কয়েক দিন চলতে পারে। এটি সাধারণ মাথাব্যথার চেয়ে বেশি, আর আক্রমণের প্রায়ই নিজস্ব উসকানি থাকে।'),
  ('migraine', 'symptoms', 0, 'A moderate or severe throbbing headache, often on one side', 'মাঝারি বা তীব্র দপদপে মাথাব্যথা, প্রায়ই এক পাশে'),
  ('migraine', 'symptoms', 1, 'Feeling or being sick', 'বমি বমি ভাব বা বমি'),
  ('migraine', 'symptoms', 2, 'Dislike of light, noise or smells', 'আলো, শব্দ বা গন্ধ অসহ্য লাগা'),
  ('migraine', 'symptoms', 3, 'Some people see flashing lights, zigzag lines or blind spots first (aura)', 'কেউ কেউ আগে ঝলকানি আলো, আঁকাবাঁকা রেখা বা অন্ধ দাগ দেখেন (অরা)'),
  ('migraine', 'causes', 0, 'Skipped meals and not drinking enough water', 'খাবার বাদ দেওয়া ও কম পানি পান'),
  ('migraine', 'causes', 1, 'Too little or too much sleep, and stress', 'কম বা বেশি ঘুম এবং মানসিক চাপ'),
  ('migraine', 'causes', 2, 'Hormone changes, such as around periods', 'হরমোনের পরিবর্তন, যেমন মাসিকের সময়'),
  ('migraine', 'causes', 3, 'Alcohol, caffeine changes, bright light, and for some people particular foods', 'অ্যালকোহল, ক্যাফেইনের হেরফের, তীব্র আলো এবং কারও কারও নির্দিষ্ট খাবার'),
  ('migraine', 'see_doctor', 0, 'Headaches that are new, getting worse or coming more often', 'নতুন, ক্রমশ বাড়ছে বা ঘন ঘন আসছে এমন মাথাব্যথা'),
  ('migraine', 'see_doctor', 1, 'Headaches that stop you working or studying', 'যে মাথাব্যথায় কাজ বা পড়াশোনা থেমে যায়'),
  ('migraine', 'see_doctor', 2, 'Needing painkillers on many days a month: ask about other options', 'মাসে অনেক দিন ব্যথার ওষুধ লাগা: অন্য উপায়ের কথা জিজ্ঞাসা করুন'),
  ('migraine', 'urgent', 0, 'A sudden, very severe headache, the worst you have had', 'হঠাৎ অত্যন্ত তীব্র মাথাব্যথা, জীবনের সবচেয়ে খারাপ'),
  ('migraine', 'urgent', 1, 'Headache with fever and a stiff neck, a rash, confusion, weakness, or trouble speaking or seeing that does not pass', 'মাথাব্যথার সঙ্গে জ্বর ও ঘাড় শক্ত, ফুসকুড়ি, বিভ্রান্তি, দুর্বলতা বা কথা বলা-দেখায় সমস্যা যা কাটছে না'),
  ('migraine', 'urgent', 2, 'A headache after a blow to the head', 'মাথায় আঘাতের পর মাথাব্যথা'),
  ('thyroid', 'about', 0, 'This page is mainly about an underactive thyroid (hypothyroidism), when the thyroid gland makes too little hormone. An overactive thyroid has different signs and needs a doctor.', 'এই পাতা মূলত থাইরয়েড কম কাজ করার (হাইপোথাইরয়েডিজম) বিষয়ে, যখন থাইরয়েড গ্রন্থি কম হরমোন তৈরি করে। থাইরয়েড বেশি কাজ করলে লক্ষণ আলাদা এবং ডাক্তার দেখাতে হয়।'),
  ('thyroid', 'symptoms', 0, 'Tiredness and low energy', 'ক্লান্তি ও শক্তির অভাব'),
  ('thyroid', 'symptoms', 1, 'Putting on weight and feeling cold', 'ওজন বাড়া ও শীত লাগা'),
  ('thyroid', 'symptoms', 2, 'Dry skin, dry thinning hair and constipation', 'শুষ্ক ত্বক, শুষ্ক পাতলা চুল ও কোষ্ঠকাঠিন্য'),
  ('thyroid', 'symptoms', 3, 'Muscle aches, low mood and trouble concentrating', 'পেশিতে ব্যথা, মন খারাপ ও মনোযোগের অসুবিধা'),
  ('thyroid', 'symptoms', 4, 'Heavier or irregular periods', 'মাসিকে বেশি রক্তপাত বা অনিয়ম'),
  ('thyroid', 'symptoms', 5, 'For an overactive thyroid instead: weight loss, a fast heartbeat, feeling hot, shaky or anxious', 'থাইরয়েড বেশি কাজ করলে এর বদলে: ওজন কমা, দ্রুত হৃৎস্পন্দন, গরম লাগা, কাঁপুনি বা উদ্বেগ'),
  ('thyroid', 'causes', 0, 'The body''s own defences attacking the thyroid (Hashimoto''s disease), the most common cause', 'শরীরের প্রতিরক্ষাই থাইরয়েডকে আক্রমণ করা (হাশিমোটো রোগ), সবচেয়ে সাধারণ কারণ'),
  ('thyroid', 'causes', 1, 'Past thyroid surgery or radioactive iodine treatment', 'আগে থাইরয়েডের অস্ত্রোপচার বা তেজস্ক্রিয় আয়োডিন চিকিৎসা'),
  ('thyroid', 'causes', 2, 'Some medicines, and in some places too little iodine in the diet', 'কিছু ওষুধ, আর কোনো কোনো এলাকায় খাবারে আয়োডিনের ঘাটতি'),
  ('thyroid', 'causes', 3, 'More common in women and as people get older; it can run in families', 'নারী ও বয়স্কদের মধ্যে বেশি; পরিবারেও চলতে পারে'),
  ('thyroid', 'see_doctor', 0, 'Several of the symptoms above that do not go away: a blood test checks thyroid hormone', 'ওপরের কয়েকটি লক্ষণ থেকে গেলে: রক্ত পরীক্ষায় থাইরয়েড হরমোন দেখা হয়'),
  ('thyroid', 'see_doctor', 1, 'Planning a pregnancy or pregnant while on thyroid medicine: tell your doctor early', 'থাইরয়েডের ওষুধ খেয়ে গর্ভধারণের পরিকল্পনা বা গর্ভাবস্থা: ডাক্তারকে আগেভাগে জানান'),
  ('thyroid', 'see_doctor', 2, 'A swelling in the neck', 'গলায় ফোলা'),
  ('thyroid', 'urgent', 0, 'Extreme drowsiness, confusion, or a very low body temperature in someone with an underactive thyroid', 'থাইরয়েড কম কাজ করা কারও অতিরিক্ত ঘুমঘুম ভাব, বিভ্রান্তি বা শরীরের তাপমাত্রা খুব কমে যাওয়া'),
  ('thyroid', 'urgent', 1, 'A very fast or irregular heartbeat with chest pain or breathlessness', 'অতি দ্রুত বা অনিয়মিত হৃৎস্পন্দনের সঙ্গে বুকে ব্যথা বা শ্বাসকষ্ট'),
  ('insomnia', 'about', 0, 'Insomnia means often finding it hard to fall asleep, stay asleep or sleep long enough, and feeling the effect in the day. Short spells are common; long ones can be helped.', 'অনিদ্রা মানে প্রায়ই ঘুম আসতে, ঘুম ধরে রাখতে বা যথেষ্ট ঘুমাতে কষ্ট হওয়া এবং দিনে তার প্রভাব টের পাওয়া। অল্প দিনের অনিদ্রা সাধারণ; দীর্ঘ হলে সাহায্য পাওয়া যায়।'),
  ('insomnia', 'symptoms', 0, 'Lying awake for a long time before sleeping', 'ঘুমানোর আগে অনেকক্ষণ জেগে শুয়ে থাকা'),
  ('insomnia', 'symptoms', 1, 'Waking up many times in the night', 'রাতে বারবার ঘুম ভেঙে যাওয়া'),
  ('insomnia', 'symptoms', 2, 'Waking too early and not getting back to sleep', 'খুব ভোরে ঘুম ভেঙে আর না ঘুমানো'),
  ('insomnia', 'symptoms', 3, 'Daytime tiredness, irritability, low mood or poor concentration', 'দিনে ক্লান্তি, খিটখিটে ভাব, মন খারাপ বা মনোযোগের অভাব'),
  ('insomnia', 'causes', 0, 'Stress, worry and low mood', 'দুশ্চিন্তা, উদ্বেগ ও মন খারাপ'),
  ('insomnia', 'causes', 1, 'Irregular sleep times, naps late in the day, and screens in bed', 'ঘুমের অনিয়মিত সময়, দিনের শেষে ঘুম এবং বিছানায় ফোন-পর্দা'),
  ('insomnia', 'causes', 2, 'Caffeine, nicotine or alcohol late in the day, and a heavy late dinner', 'দিনের শেষে ক্যাফেইন, নিকোটিন বা অ্যালকোহল এবং রাতে ভারী খাবার'),
  ('insomnia', 'causes', 3, 'A hot, noisy or bright room, pain, other health conditions and some medicines', 'গরম, গোলমেলে বা আলোকিত ঘর, ব্যথা, অন্য অসুখ ও কিছু ওষুধ'),
  ('insomnia', 'see_doctor', 0, 'Poor sleep for more than three or four weeks, or it affects your day', 'তিন-চার সপ্তাহের বেশি খারাপ ঘুম, বা দিনের কাজে প্রভাব পড়া'),
  ('insomnia', 'see_doctor', 1, 'Loud snoring with pauses in breathing, or falling asleep while driving or working', 'জোরে নাক ডাকার সঙ্গে শ্বাস থেমে যাওয়া, বা গাড়ি চালানো বা কাজের সময় ঘুমিয়ে পড়া'),
  ('insomnia', 'see_doctor', 2, 'Using alcohol or sleeping tablets to get to sleep', 'ঘুমের জন্য অ্যালকোহল বা ঘুমের বড়ির ওপর নির্ভর করা'),
  ('insomnia', 'urgent', 0, 'Feeling hopeless, or thoughts of harming yourself: talk to someone you trust and get help now', 'হতাশা, বা নিজের ক্ষতি করার চিন্তা: বিশ্বস্ত কারও সঙ্গে কথা বলুন এবং এখনই সাহায্য নিন'),
  ('pcos', 'about', 0, 'Polycystic ovary syndrome (PCOS) is a common hormone condition that affects how the ovaries work. It is linked to insulin and weight, and it can be managed.', 'পলিসিস্টিক ওভারি সিনড্রোম (পিসিওএস) হরমোনজনিত সাধারণ অবস্থা, যা ডিম্বাশয়ের কাজকে প্রভাবিত করে। এটি ইনসুলিন ও ওজনের সঙ্গে জড়িত এবং নিয়ন্ত্রণে রাখা যায়।'),
  ('pcos', 'symptoms', 0, 'Irregular periods, or no periods', 'অনিয়মিত মাসিক, বা মাসিক বন্ধ'),
  ('pcos', 'symptoms', 1, 'Trouble getting pregnant', 'গর্ভধারণে অসুবিধা'),
  ('pcos', 'symptoms', 2, 'Extra hair on the face or body, and thinning hair on the head', 'মুখে বা শরীরে বাড়তি লোম এবং মাথার চুল পাতলা হওয়া'),
  ('pcos', 'symptoms', 3, 'Acne or oily skin, and weight gain', 'ব্রণ বা তৈলাক্ত ত্বক এবং ওজন বাড়া'),
  ('pcos', 'causes', 0, 'The exact cause is not known', 'সঠিক কারণ জানা নেই'),
  ('pcos', 'causes', 1, 'High insulin levels (insulin resistance) can push the ovaries to make more male hormone', 'ইনসুলিন বেশি থাকলে (ইনসুলিন রেজিস্ট্যান্স) ডিম্বাশয় বেশি পুরুষ হরমোন তৈরি করতে পারে'),
  ('pcos', 'causes', 2, 'It often runs in families, and extra weight can make it worse', 'এটি প্রায়ই পরিবারে চলে এবং বাড়তি ওজন একে বাড়াতে পারে'),
  ('pcos', 'see_doctor', 0, 'Periods that are irregular, far apart or have stopped', 'অনিয়মিত, অনেক দূরে দূরে বা বন্ধ হয়ে যাওয়া মাসিক'),
  ('pcos', 'see_doctor', 1, 'Trying for a baby for a year without success', 'এক বছর চেষ্টা করেও সন্তান না আসা'),
  ('pcos', 'see_doctor', 2, 'PCOS raises the chance of type 2 diabetes, high blood pressure and high cholesterol: ask about regular checks', 'পিসিওএসে টাইপ ২ ডায়াবেটিস, উচ্চ রক্তচাপ ও উচ্চ কোলেস্টেরলের ঝুঁকি বাড়ে: নিয়মিত পরীক্ষার কথা জিজ্ঞাসা করুন'),
  ('pcos', 'see_doctor', 3, 'Low mood or anxiety that is affecting daily life', 'মন খারাপ বা উদ্বেগ যা দৈনন্দিন জীবনে প্রভাব ফেলছে'),
  ('pcos', 'urgent', 0, 'Very heavy bleeding that soaks through pads quickly, with dizziness or faintness', 'খুব বেশি রক্তপাত যাতে দ্রুত প্যাড ভিজে যায়, সঙ্গে মাথা ঘোরা বা অজ্ঞান ভাব'),
  ('pcos', 'urgent', 1, 'Sudden severe pain low in the tummy', 'তলপেটে হঠাৎ তীব্র ব্যথা'),
  ('hypertension', 'about', 0, 'High blood pressure (hypertension) means the force of blood on your artery walls is too high for a long time. It usually causes no symptoms, so it is found by measuring.', 'উচ্চ রক্তচাপে ধমনির দেয়ালে রক্তের চাপ দীর্ঘ সময় ধরে বেশি থাকে। সাধারণত কোনো লক্ষণ থাকে না, তাই মেপেই ধরা পড়ে।'),
  ('hypertension', 'symptoms', 0, 'Most people feel nothing at all, even when it is high', 'বেশির ভাগ মানুষ কিছুই টের পান না, চাপ বেশি থাকলেও'),
  ('hypertension', 'symptoms', 1, 'Very high pressure can cause a bad headache, blurred vision, nosebleeds or chest pain', 'খুব বেশি চাপে তীব্র মাথাব্যথা, ঝাপসা দেখা, নাক দিয়ে রক্ত বা বুকে ব্যথা হতে পারে'),
  ('hypertension', 'symptoms', 2, 'Over the years it silently strains the heart, brain, kidneys and eyes', 'বছরের পর বছর এটি নীরবে হৃদ্‌পিণ্ড, মস্তিষ্ক, কিডনি ও চোখের ওপর চাপ ফেলে'),
  ('hypertension', 'causes', 0, 'Too much salt, and too little fruit and vegetables', 'বেশি লবণ এবং কম ফল ও শাকসবজি'),
  ('hypertension', 'causes', 1, 'Being overweight, and little physical activity', 'ওজন বেশি এবং কম শারীরিক পরিশ্রম'),
  ('hypertension', 'causes', 2, 'Drinking too much alcohol, smoking or chewing tobacco, and stress', 'বেশি মদ্যপান, ধূমপান বা তামাক চিবানো এবং মানসিক চাপ'),
  ('hypertension', 'causes', 3, 'Getting older, high blood pressure in the family, and long-term kidney problems', 'বয়স বাড়া, পরিবারে উচ্চ রক্তচাপ এবং দীর্ঘমেয়াদি কিডনির সমস্যা'),
  ('hypertension', 'see_doctor', 0, 'Have your pressure measured regularly, even if you feel well', 'ভালো লাগলেও নিয়মিত রক্তচাপ মাপান'),
  ('hypertension', 'see_doctor', 1, 'A reading at or above 140/90 on more than one day', 'একাধিক দিন ১৪০/৯০ বা তার বেশি মাপা'),
  ('hypertension', 'see_doctor', 2, 'If you take blood pressure medicine: dizziness on standing, or a very low reading', 'রক্তচাপের ওষুধ খেলে: দাঁড়ালে মাথা ঘোরা, বা খুব কম মাপা'),
  ('hypertension', 'urgent', 0, 'A reading of 180/120 or higher with chest pain, a severe headache, breathlessness, confusion or weakness', '১৮০/১২০ বা তার বেশি মাপার সঙ্গে বুকে ব্যথা, তীব্র মাথাব্যথা, শ্বাসকষ্ট, বিভ্রান্তি বা দুর্বলতা'),
  ('hypertension', 'urgent', 1, 'Face drooping, an arm that will not lift, or slurred speech', 'মুখ বেঁকে যাওয়া, হাত তুলতে না পারা বা কথা জড়িয়ে যাওয়া'),
  ('high-cholesterol', 'about', 0, 'High cholesterol means too much fat in the blood (often called bad or LDL cholesterol). It builds up in the arteries over years and raises the risk of heart disease and stroke.', 'উচ্চ কোলেস্টেরল মানে রক্তে চর্বি বেশি (প্রায়ই খারাপ বা এলডিএল কোলেস্টেরল)। এটি বছরের পর বছর ধমনিতে জমে হৃদ্‌রোগ ও স্ট্রোকের ঝুঁকি বাড়ায়।'),
  ('high-cholesterol', 'symptoms', 0, 'Usually no symptoms: only a blood test shows it', 'সাধারণত কোনো লক্ষণ নেই: শুধু রক্ত পরীক্ষায় ধরা পড়ে'),
  ('high-cholesterol', 'symptoms', 1, 'Rarely, in inherited high cholesterol: yellow patches around the eyes or lumps on the tendons', 'বংশগত উচ্চ কোলেস্টেরলে কদাচিৎ: চোখের চারপাশে হলুদ দাগ বা টেন্ডনে গুটি'),
  ('high-cholesterol', 'symptoms', 2, 'The harm shows later as chest pain, heart attack or stroke', 'ক্ষতি দেখা দেয় পরে বুকে ব্যথা, হার্ট অ্যাটাক বা স্ট্রোক হিসেবে'),
  ('high-cholesterol', 'causes', 0, 'A lot of saturated and trans fat: fatty meat, ghee, butter, fried food and bakery snacks', 'প্রচুর স্যাচুরেটেড ও ট্রান্স ফ্যাট: চর্বিযুক্ত মাংস, ঘি, মাখন, ভাজাপোড়া ও বেকারির খাবার'),
  ('high-cholesterol', 'causes', 1, 'Being overweight, little activity, and smoking', 'ওজন বেশি, কম পরিশ্রম ও ধূমপান'),
  ('high-cholesterol', 'causes', 2, 'Diabetes, an underactive thyroid and some other conditions', 'ডায়াবেটিস, থাইরয়েড কম কাজ করা ও অন্য কিছু অবস্থা'),
  ('high-cholesterol', 'causes', 3, 'It can run in families (familial hypercholesterolaemia), even in slim people', 'এটি পরিবারে চলতে পারে (ফ্যামিলিয়াল হাইপারকোলেস্টেরোলেমিয়া), রোগা মানুষেরও হতে পারে'),
  ('high-cholesterol', 'see_doctor', 0, 'Ask for a cholesterol blood test, especially over 40 or with diabetes or high blood pressure', 'কোলেস্টেরলের রক্ত পরীক্ষা চান, বিশেষ করে ৪০-এর বেশি বয়সে বা ডায়াবেটিস ও উচ্চ রক্তচাপ থাকলে'),
  ('high-cholesterol', 'see_doctor', 1, 'A parent or sibling who had a heart attack or stroke young', 'বাবা-মা বা ভাইবোনের কম বয়সে হার্ট অ্যাটাক বা স্ট্রোক হওয়া'),
  ('high-cholesterol', 'see_doctor', 2, 'If you take cholesterol medicine: unexplained muscle pain or weakness', 'কোলেস্টেরলের ওষুধ খেলে: অকারণ পেশিতে ব্যথা বা দুর্বলতা'),
  ('high-cholesterol', 'urgent', 0, 'Chest pain or pressure, pain spreading to the arm or jaw, sweating or breathlessness', 'বুকে ব্যথা বা চাপ, হাত বা চোয়ালে ছড়ানো ব্যথা, ঘাম বা শ্বাসকষ্ট'),
  ('high-cholesterol', 'urgent', 1, 'Face drooping, arm weakness or slurred speech', 'মুখ বেঁকে যাওয়া, হাতে দুর্বলতা বা কথা জড়িয়ে যাওয়া'),
  ('anaemia', 'about', 0, 'Iron-deficiency anaemia means too few healthy red blood cells because the body lacks iron. It is common, especially in women and children, and it can be treated.', 'আয়রনের অভাবজনিত রক্তস্বল্পতায় শরীরে আয়রন কম থাকায় সুস্থ লোহিত রক্তকণিকা কম হয়। এটি সাধারণ, বিশেষ করে নারী ও শিশুদের মধ্যে, এবং চিকিৎসা সম্ভব।'),
  ('anaemia', 'symptoms', 0, 'Tiredness and lack of energy', 'ক্লান্তি ও শক্তির অভাব'),
  ('anaemia', 'symptoms', 1, 'Shortness of breath, especially on climbing stairs', 'শ্বাসকষ্ট, বিশেষ করে সিঁড়ি ভাঙলে'),
  ('anaemia', 'symptoms', 2, 'Pale skin, and pale inside the eyelids', 'ত্বক ফ্যাকাশে, চোখের নিচের পাতার ভেতরও ফ্যাকাশে'),
  ('anaemia', 'symptoms', 3, 'A pounding heartbeat, headaches and dizziness', 'বুক ধড়ফড়, মাথাব্যথা ও মাথা ঘোরা'),
  ('anaemia', 'symptoms', 4, 'Brittle nails, hair loss and a sore tongue', 'ভঙ্গুর নখ, চুল পড়া ও জিভে ঘা'),
  ('anaemia', 'causes', 0, 'Too little iron in food: few leafy greens, pulses, meat, fish or eggs', 'খাবারে আয়রন কম: শাক, ডাল, মাংস, মাছ বা ডিম কম'),
  ('anaemia', 'causes', 1, 'Blood loss: heavy periods, or bleeding in the gut such as from worms or ulcers', 'রক্তক্ষরণ: বেশি মাসিক, বা পেটের ভেতরে রক্তপাত, যেমন কৃমি বা আলসার থেকে'),
  ('anaemia', 'causes', 2, 'Pregnancy and fast growth in children, when the body needs more iron', 'গর্ভাবস্থা ও শিশুর দ্রুত বৃদ্ধি, যখন শরীরে বেশি আয়রন লাগে'),
  ('anaemia', 'causes', 3, 'Tea or coffee with meals can reduce how much iron the body takes in; some gut conditions do the same', 'খাবারের সঙ্গে চা বা কফি আয়রন শোষণ কমাতে পারে; পেটের কিছু অসুখেও তা হয়'),
  ('anaemia', 'see_doctor', 0, 'Tiredness or paleness that does not improve: a blood test confirms anaemia', 'ক্লান্তি বা ফ্যাকাশে ভাব না কমলে: রক্ত পরীক্ষায় রক্তস্বল্পতা নিশ্চিত হয়'),
  ('anaemia', 'see_doctor', 1, 'Heavy periods, or you are pregnant or planning a pregnancy', 'বেশি মাসিক, বা গর্ভবতী অথবা গর্ভধারণের পরিকল্পনা'),
  ('anaemia', 'see_doctor', 2, 'A child who is pale, tired or not growing well', 'শিশু ফ্যাকাশে, ক্লান্ত বা ঠিকমতো বাড়ছে না'),
  ('anaemia', 'see_doctor', 3, 'Do not start iron tablets on your own: ask first, since the cause matters', 'নিজে নিজে আয়রনের বড়ি শুরু করবেন না: আগে জিজ্ঞাসা করুন, কারণ জানা জরুরি'),
  ('anaemia', 'urgent', 0, 'Chest pain, severe breathlessness, or fainting', 'বুকে ব্যথা, তীব্র শ্বাসকষ্ট বা অজ্ঞান হয়ে যাওয়া'),
  ('anaemia', 'urgent', 1, 'Black or bloody stools, or vomiting blood', 'কালো বা রক্তমাখা পায়খানা, বা রক্তবমি'),
  ('gout', 'about', 0, 'Gout is a kind of arthritis caused by too much uric acid in the blood, which forms sharp crystals in a joint. Attacks come suddenly and settle, and they tend to return without care.', 'গাউট এক ধরনের আর্থ্রাইটিস, যা রক্তে ইউরিক অ্যাসিড বেশি হয়ে জোড়ায় ধারালো স্ফটিক জমলে হয়। আক্রমণ হঠাৎ আসে ও কমে, যত্ন না নিলে ফিরে আসে।'),
  ('gout', 'symptoms', 0, 'Sudden, severe pain in a joint, most often the big toe', 'কোনো জোড়ায় হঠাৎ তীব্র ব্যথা, সবচেয়ে বেশি বুড়ো আঙুলে'),
  ('gout', 'symptoms', 1, 'The joint is swollen, hot, red and too tender to touch', 'জোড়া ফোলা, গরম, লাল এবং ছোঁয়া যায় না এমন ব্যথা'),
  ('gout', 'symptoms', 2, 'An attack often starts at night and usually settles in about a week', 'আক্রমণ প্রায়ই রাতে শুরু হয় এবং সাধারণত এক সপ্তাহ মতো পরে কমে'),
  ('gout', 'symptoms', 3, 'Shiny, peeling skin over the joint afterwards', 'পরে জোড়ার ওপরের চামড়া চকচকে হয়ে উঠে যাওয়া'),
  ('gout', 'causes', 0, 'High uric acid, from the body making too much or the kidneys clearing too little', 'ইউরিক অ্যাসিড বেশি: শরীর বেশি তৈরি করে বা কিডনি কম বের করে'),
  ('gout', 'causes', 1, 'Organ meat, red meat, some seafood, sugary drinks and alcohol, especially beer', 'কলিজা-মগজ, লাল মাংস, কিছু সামুদ্রিক খাবার, মিষ্টি পানীয় ও মদ, বিশেষ করে বিয়ার'),
  ('gout', 'causes', 2, 'Being overweight, and being a man or a woman after menopause', 'ওজন বেশি, এবং পুরুষ বা মেনোপজের পরের নারী হওয়া'),
  ('gout', 'causes', 3, 'Kidney disease, some water tablets, and gout in the family', 'কিডনির রোগ, কিছু প্রস্রাববর্ধক ওষুধ এবং পরিবারে গাউট'),
  ('gout', 'see_doctor', 0, 'A first attack of sudden severe joint pain', 'হঠাৎ তীব্র জোড়া ব্যথার প্রথম আক্রমণ'),
  ('gout', 'see_doctor', 1, 'Attacks that come back, or lumps under the skin near joints', 'ঘন ঘন আক্রমণ, বা জোড়ার কাছে চামড়ার নিচে গুটি'),
  ('gout', 'see_doctor', 2, 'Ask about a blood uric acid check and about long-term care', 'রক্তে ইউরিক অ্যাসিড পরীক্ষা ও দীর্ঘমেয়াদি যত্নের কথা জিজ্ঞাসা করুন'),
  ('gout', 'urgent', 0, 'A hot, swollen joint with fever or shaking chills: it may be an infection', 'গরম, ফোলা জোড়ার সঙ্গে জ্বর বা কাঁপুনি: সংক্রমণ হতে পারে'),
  ('gout', 'urgent', 1, 'Pain in a joint after an injury, or a joint you cannot move at all', 'আঘাতের পর জোড়ায় ব্যথা, বা একেবারে নড়ানো যায় না এমন জোড়া'),
  ('acid-reflux', 'about', 0, 'Acid reflux is when stomach acid comes back up into the food pipe. Having it often is called GERD, and it usually improves with changes to meals and habits.', 'অ্যাসিড রিফ্লাক্সে পাকস্থলীর অ্যাসিড খাদ্যনালিতে ফিরে আসে। ঘন ঘন হলে একে জিইআরডি বলে, আর খাবার ও অভ্যাস বদলালে সাধারণত উন্নতি হয়।'),
  ('acid-reflux', 'symptoms', 0, 'Heartburn: a burning feeling in the chest, often after eating or when lying down', 'বুক জ্বালা: বুকে জ্বলুনি, প্রায়ই খাওয়ার পরে বা শুয়ে পড়লে'),
  ('acid-reflux', 'symptoms', 1, 'A sour or bitter taste as acid comes up into the mouth', 'মুখে টক বা তেতো স্বাদ, অ্যাসিড উঠে এলে'),
  ('acid-reflux', 'symptoms', 2, 'Bloating, burping and feeling sick', 'পেট ফাঁপা, ঢেকুর ও বমি বমি ভাব'),
  ('acid-reflux', 'symptoms', 3, 'A cough, hoarse voice or sore throat, often at night', 'কাশি, গলা বসে যাওয়া বা গলাব্যথা, প্রায়ই রাতে'),
  ('acid-reflux', 'causes', 0, 'Large, fatty or spicy meals, and eating late at night', 'বড়, চর্বিযুক্ত বা ঝাল খাবার এবং রাতে দেরিতে খাওয়া'),
  ('acid-reflux', 'causes', 1, 'Tea, coffee, chocolate, citrus, fizzy drinks and alcohol for some people', 'কারও কারও জন্য চা, কফি, চকোলেট, টকজাতীয় ফল, কোমল পানীয় ও মদ'),
  ('acid-reflux', 'causes', 2, 'Smoking, being overweight, and pregnancy', 'ধূমপান, ওজন বেশি এবং গর্ভাবস্থা'),
  ('acid-reflux', 'causes', 3, 'Lying down soon after a meal, tight clothes, and a hiatus hernia', 'খাওয়ার পরপর শুয়ে পড়া, আঁটসাঁট পোশাক এবং হায়াটাস হার্নিয়া'),
  ('acid-reflux', 'see_doctor', 0, 'Heartburn on most days for three weeks or more', 'তিন সপ্তাহ বা তার বেশি প্রায় প্রতিদিন বুক জ্বালা'),
  ('acid-reflux', 'see_doctor', 1, 'Trouble or pain when swallowing, or food that feels stuck', 'গিলতে কষ্ট বা ব্যথা, বা খাবার আটকে থাকার অনুভূতি'),
  ('acid-reflux', 'see_doctor', 2, 'Losing weight without trying, or being over 55 with new symptoms', 'চেষ্টা ছাড়াই ওজন কমা, বা ৫৫-এর বেশি বয়সে নতুন লক্ষণ'),
  ('acid-reflux', 'see_doctor', 3, 'Needing indigestion medicine most days', 'প্রায় প্রতিদিন অম্বলের ওষুধ লাগা'),
  ('acid-reflux', 'urgent', 0, 'Chest pain that spreads to the arm or jaw, or comes with sweating or breathlessness: it may be the heart', 'বুকের ব্যথা হাত বা চোয়ালে ছড়ানো, বা ঘাম বা শ্বাসকষ্টসহ: এটি হৃদ্‌রোগ হতে পারে'),
  ('acid-reflux', 'urgent', 1, 'Vomiting blood, or black sticky stools', 'রক্তবমি, বা কালো আঠালো পায়খানা'),
  ('dengue', 'about', 0, 'Dengue is a viral illness spread by the bite of Aedes mosquitoes, which bite mostly in the daytime. Most people recover at home, but some get a severe form.', 'ডেঙ্গু ভাইরাসজনিত অসুখ, যা এডিস মশার কামড়ে ছড়ায়; এই মশা বেশি কামড়ায় দিনের বেলায়। বেশির ভাগ মানুষ ঘরেই সেরে ওঠেন, তবে কারও কারও মারাত্মক রূপ হয়।'),
  ('dengue', 'symptoms', 0, 'Sudden high fever', 'হঠাৎ উচ্চ জ্বর'),
  ('dengue', 'symptoms', 1, 'Severe headache and pain behind the eyes', 'তীব্র মাথাব্যথা ও চোখের পেছনে ব্যথা'),
  ('dengue', 'symptoms', 2, 'Muscle and joint pain, and feeling or being sick', 'পেশি ও জোড়ায় ব্যথা এবং বমি বমি ভাব বা বমি'),
  ('dengue', 'symptoms', 3, 'A skin rash, and mild bleeding from the nose or gums', 'ত্বকে র‍্যাশ এবং নাক বা মাড়ি থেকে সামান্য রক্ত'),
  ('dengue', 'causes', 0, 'The dengue virus, passed on by an infected Aedes mosquito', 'ডেঙ্গু ভাইরাস, সংক্রমিত এডিস মশার কামড়ে ছড়ায়'),
  ('dengue', 'causes', 1, 'Clean standing water near homes, such as in pots, tyres and coolers, lets the mosquitoes breed', 'ঘরের কাছে জমে থাকা পরিষ্কার পানি, যেমন টব, টায়ার ও কুলারে, মশার বংশবৃদ্ধি ঘটায়'),
  ('dengue', 'see_doctor', 0, 'Fever with the symptoms above, especially in or after a rainy season', 'ওপরের লক্ষণসহ জ্বর, বিশেষ করে বর্ষায় বা তার পরে'),
  ('dengue', 'see_doctor', 1, 'A blood test is needed to know; rest and drink plenty of fluids while waiting', 'নিশ্চিত হতে রক্ত পরীক্ষা লাগে; অপেক্ষার সময় বিশ্রাম নিন ও প্রচুর তরল খান'),
  ('dengue', 'see_doctor', 2, 'Ask a doctor before taking any painkiller: aspirin and ibuprofen can raise the risk of bleeding', 'ব্যথার ওষুধ খাওয়ার আগে ডাক্তারকে জিজ্ঞাসা করুন: অ্যাসপিরিন ও আইবুপ্রোফেন রক্তপাতের ঝুঁকি বাড়াতে পারে'),
  ('dengue', 'urgent', 0, 'As the fever falls, warning signs: severe belly pain, repeated vomiting, fast breathing, bleeding gums or nose, blood in vomit or stool', 'জ্বর কমার সময় সতর্ক সংকেত: তীব্র পেটব্যথা, বারবার বমি, দ্রুত শ্বাস, মাড়ি বা নাক থেকে রক্ত, বমি বা পায়খানায় রক্ত'),
  ('dengue', 'urgent', 1, 'Extreme tiredness or restlessness, cold clammy skin: go to hospital at once', 'অতিরিক্ত দুর্বলতা বা অস্থিরতা, ঠান্ডা ঘামে ভেজা ত্বক: এখনই হাসপাতালে যান'),
  ('jaundice', 'about', 0, 'Jaundice is yellowing of the skin and the whites of the eyes. It is a sign of another problem, such as a liver infection or a blocked bile duct, not an illness by itself.', 'জন্ডিস মানে ত্বক ও চোখের সাদা অংশ হলুদ হয়ে যাওয়া। এটি অন্য সমস্যার লক্ষণ, যেমন লিভারের সংক্রমণ বা পিত্তনালি বন্ধ হওয়া, নিজে আলাদা অসুখ নয়।'),
  ('jaundice', 'symptoms', 0, 'Yellow skin and yellow whites of the eyes', 'ত্বক ও চোখের সাদা অংশ হলুদ'),
  ('jaundice', 'symptoms', 1, 'Dark urine and pale stools', 'গাঢ় প্রস্রাব ও ফ্যাকাশে পায়খানা'),
  ('jaundice', 'symptoms', 2, 'Itchy skin, tiredness and loss of appetite', 'চামড়া চুলকানো, ক্লান্তি ও ক্ষুধামান্দ্য'),
  ('jaundice', 'symptoms', 3, 'Sometimes fever, feeling sick and pain in the upper right of the tummy', 'কখনো জ্বর, বমি বমি ভাব ও পেটের ওপরের ডান দিকে ব্যথা'),
  ('jaundice', 'causes', 0, 'Hepatitis A and E, spread by unclean food and water, and hepatitis B and C, spread by blood and body fluids', 'হেপাটাইটিস এ ও ই, অপরিষ্কার খাবার-পানি থেকে এবং হেপাটাইটিস বি ও সি, রক্ত ও শরীরের তরল থেকে'),
  ('jaundice', 'causes', 1, 'Gallstones or a blocked bile duct', 'পিত্তথলির পাথর বা পিত্তনালি বন্ধ'),
  ('jaundice', 'causes', 2, 'Heavy alcohol use, some medicines and other liver diseases', 'অতিরিক্ত মদ্যপান, কিছু ওষুধ ও লিভারের অন্য রোগ'),
  ('jaundice', 'causes', 3, 'Newborn babies often have mild jaundice that settles, but a doctor should check', 'নবজাতকের প্রায়ই হালকা জন্ডিস হয় যা সেরে যায়, তবে ডাক্তারের দেখা উচিত'),
  ('jaundice', 'see_doctor', 0, 'Yellow skin or eyes always needs a doctor to find the cause', 'ত্বক বা চোখ হলুদ হলে কারণ জানতে সবসময় ডাক্তার দেখান'),
  ('jaundice', 'see_doctor', 1, 'Avoid alcohol and ask before taking any medicine until the liver is checked', 'লিভার পরীক্ষা না হওয়া পর্যন্ত মদ এড়ান এবং ওষুধ খাওয়ার আগে জিজ্ঞাসা করুন'),
  ('jaundice', 'see_doctor', 2, 'A newborn with yellow skin, especially in the first day or after a week', 'নবজাতকের ত্বক হলুদ, বিশেষ করে প্রথম দিনে বা এক সপ্তাহ পরে'),
  ('jaundice', 'urgent', 0, 'Confusion, drowsiness, or hard to wake', 'বিভ্রান্তি, ঘুমঘুম ভাব বা জাগানো কঠিন'),
  ('jaundice', 'urgent', 1, 'Severe belly pain, vomiting blood, or a high fever with shaking', 'তীব্র পেটব্যথা, রক্তবমি, বা কাঁপুনিসহ উচ্চ জ্বর'),
  ('typhoid', 'about', 0, 'Typhoid is a bacterial infection (Salmonella Typhi) spread by food and water contaminated with the faeces of an infected person. It needs medical treatment.', 'টাইফয়েড ব্যাকটেরিয়াজনিত সংক্রমণ (সালমোনেলা টাইফি), সংক্রমিত ব্যক্তির মলে দূষিত খাবার ও পানি থেকে ছড়ায়। এর চিকিৎসা লাগে।'),
  ('typhoid', 'symptoms', 0, 'A fever that climbs over several days', 'কয়েক দিন ধরে বাড়তে থাকা জ্বর'),
  ('typhoid', 'symptoms', 1, 'Headache, weakness and loss of appetite', 'মাথাব্যথা, দুর্বলতা ও ক্ষুধামান্দ্য'),
  ('typhoid', 'symptoms', 2, 'Stomach pain, with constipation or diarrhoea', 'পেটব্যথা, সঙ্গে কোষ্ঠকাঠিন্য বা ডায়রিয়া'),
  ('typhoid', 'symptoms', 3, 'Sometimes a rash of small pink spots', 'কখনো ছোট গোলাপি দাগের র‍্যাশ'),
  ('typhoid', 'causes', 0, 'Drinking unboiled or unsafe water, and eating raw or street food washed in it', 'না ফোটানো বা অনিরাপদ পানি পান এবং সেই পানিতে ধোয়া কাঁচা বা রাস্তার খাবার'),
  ('typhoid', 'causes', 1, 'Poor hand washing after the toilet and before food', 'টয়লেটের পর ও খাওয়ার আগে হাত ভালোভাবে না ধোয়া'),
  ('typhoid', 'causes', 2, 'A person who carries the germ without symptoms can spread it', 'লক্ষণহীন বাহকও জীবাণু ছড়াতে পারেন'),
  ('typhoid', 'see_doctor', 0, 'A fever that lasts more than a few days, especially after eating out or travel', 'কয়েক দিনের বেশি জ্বর, বিশেষ করে বাইরে খাওয়া বা ভ্রমণের পর'),
  ('typhoid', 'see_doctor', 1, 'A blood or stool test is needed to know; do not take leftover antibiotics', 'জানতে রক্ত বা মল পরীক্ষা লাগে; আগের বাকি অ্যান্টিবায়োটিক খাবেন না'),
  ('typhoid', 'see_doctor', 2, 'Vaccination and safe water and food habits help prevent it', 'টিকা এবং নিরাপদ পানি ও খাবারের অভ্যাস প্রতিরোধে সাহায্য করে'),
  ('typhoid', 'urgent', 0, 'Severe belly pain, blood in the stool, or repeated vomiting', 'তীব্র পেটব্যথা, পায়খানায় রক্ত বা বারবার বমি'),
  ('typhoid', 'urgent', 1, 'Confusion, extreme weakness, or unable to drink', 'বিভ্রান্তি, অত্যন্ত দুর্বলতা বা পানি পান করতে না পারা'),
  ('viral-fever', 'about', 0, 'A viral fever is a raised temperature caused by a virus, such as a cold or flu. It usually passes in a few days with rest and plenty of fluids.', 'ভাইরাল জ্বর হলো ভাইরাসের কারণে, যেমন সর্দি বা ফ্লু, শরীরের তাপমাত্রা বেড়ে যাওয়া। বিশ্রাম ও প্রচুর তরলে সাধারণত কয়েক দিনে সেরে যায়।'),
  ('viral-fever', 'symptoms', 0, 'A temperature of 38°C or higher, with sweats or chills', '৩৮° সেলসিয়াস বা বেশি তাপমাত্রা, ঘাম বা কাঁপুনিসহ'),
  ('viral-fever', 'symptoms', 1, 'Headache, body aches and tiredness', 'মাথাব্যথা, গা ব্যথা ও ক্লান্তি'),
  ('viral-fever', 'symptoms', 2, 'Loss of appetite, sore throat, runny nose or cough', 'ক্ষুধামান্দ্য, গলাব্যথা, সর্দি বা কাশি'),
  ('viral-fever', 'causes', 0, 'Common viruses such as cold and flu, spread by coughs, sneezes and touch', 'সর্দি ও ফ্লুর মতো সাধারণ ভাইরাস, কাশি, হাঁচি ও স্পর্শে ছড়ায়'),
  ('viral-fever', 'causes', 1, 'Fever is also an early sign of illnesses such as dengue, typhoid and malaria, so a long fever needs tests', 'জ্বর ডেঙ্গু, টাইফয়েড ও ম্যালেরিয়ার মতো অসুখেরও প্রাথমিক লক্ষণ, তাই দীর্ঘ জ্বরে পরীক্ষা লাগে'),
  ('viral-fever', 'see_doctor', 0, 'Fever that lasts more than three days, or keeps rising', 'তিন দিনের বেশি জ্বর, বা ক্রমশ বাড়তে থাকা জ্বর'),
  ('viral-fever', 'see_doctor', 1, 'Any fever in a baby under three months', 'তিন মাসের কম বয়সী শিশুর যেকোনো জ্বর'),
  ('viral-fever', 'see_doctor', 2, 'Fever in someone who is pregnant, older, or has a long-term illness', 'গর্ভবতী, বয়স্ক বা দীর্ঘমেয়াদি অসুখে ভোগা কারও জ্বর'),
  ('viral-fever', 'urgent', 0, 'A stiff neck, a rash that does not fade under a pressed glass, or a fit', 'ঘাড় শক্ত, গ্লাস চাপলেও না মেলানো র‍্যাশ, বা খিঁচুনি'),
  ('viral-fever', 'urgent', 1, 'Trouble breathing, confusion, or not drinking or passing urine', 'শ্বাসকষ্ট, বিভ্রান্তি, বা পানি না খাওয়া ও প্রস্রাব না হওয়া'),
  ('food-poisoning', 'about', 0, 'Food poisoning is an illness from eating food with harmful germs or toxins. Most cases settle in a few days at home, with plenty of fluids.', 'খাদ্যে বিষক্রিয়া ক্ষতিকর জীবাণু বা বিষযুক্ত খাবার খেলে হয়। বেশির ভাগ ক্ষেত্রে কয়েক দিনে ঘরেই, প্রচুর তরল খেয়ে, সেরে যায়।'),
  ('food-poisoning', 'symptoms', 0, 'Feeling sick and vomiting', 'বমি বমি ভাব ও বমি'),
  ('food-poisoning', 'symptoms', 1, 'Watery diarrhoea, sometimes with blood', 'পানির মতো ডায়রিয়া, কখনো রক্তসহ'),
  ('food-poisoning', 'symptoms', 2, 'Stomach cramps', 'পেটে মোচড়ানো ব্যথা'),
  ('food-poisoning', 'symptoms', 3, 'A fever, aching and tiredness', 'জ্বর, গা ব্যথা ও ক্লান্তি'),
  ('food-poisoning', 'causes', 0, 'Undercooked meat, eggs or fish, and food left out in the heat', 'কম সেদ্ধ মাংস, ডিম বা মাছ এবং গরমে খোলা পড়ে থাকা খাবার'),
  ('food-poisoning', 'causes', 1, 'Unwashed fruit and vegetables, unsafe water, and dirty hands or utensils', 'না ধোয়া ফল ও সবজি, অনিরাপদ পানি এবং নোংরা হাত বা বাসন'),
  ('food-poisoning', 'causes', 2, 'Reheated rice and cooked food kept too long before eating', 'পুনরায় গরম করা ভাত এবং রান্না করা খাবার অনেকক্ষণ রেখে খাওয়া'),
  ('food-poisoning', 'see_doctor', 0, 'Symptoms that last more than a few days, or blood in the stool', 'কয়েক দিনের বেশি লক্ষণ, বা পায়খানায় রক্ত'),
  ('food-poisoning', 'see_doctor', 1, 'Signs of dehydration: very thirsty, dark urine or very little, dizziness', 'পানিশূন্যতার লক্ষণ: খুব পিপাসা, গাঢ় বা খুব কম প্রস্রাব, মাথা ঘোরা'),
  ('food-poisoning', 'see_doctor', 2, 'Babies, young children, older people, pregnant women and people with weak immunity should get help early', 'শিশু, ছোট বাচ্চা, বয়স্ক, গর্ভবতী ও দুর্বল রোগপ্রতিরোধের মানুষ আগেভাগে সাহায্য নিন'),
  ('food-poisoning', 'urgent', 0, 'Cannot keep any fluids down, or very drowsy', 'কোনো তরলই পেটে রাখতে পারছেন না, বা খুব ঘুমঘুম ভাব'),
  ('food-poisoning', 'urgent', 1, 'Blurred vision, weakness or tingling after eating (rare, but serious)', 'খাওয়ার পর ঝাপসা দেখা, দুর্বলতা বা ঝিনঝিন (বিরল, কিন্তু গুরুতর)'),
  ('diarrhoea', 'about', 0, 'Diarrhoea means loose, watery stools three or more times a day. The main danger is losing too much fluid, especially in children and older people.', 'ডায়রিয়া মানে দিনে তিনবার বা বেশি পাতলা পানির মতো পায়খানা। প্রধান বিপদ হলো বেশি তরল হারানো, বিশেষ করে শিশু ও বয়স্কদের।'),
  ('diarrhoea', 'symptoms', 0, 'Loose or watery stools, three or more times a day', 'দিনে তিনবার বা বেশি পাতলা বা পানির মতো পায়খানা'),
  ('diarrhoea', 'symptoms', 1, 'Stomach cramps and a sudden urge to go', 'পেটে মোচড় ও হঠাৎ পায়খানার চাপ'),
  ('diarrhoea', 'symptoms', 2, 'Feeling sick, and sometimes a fever', 'বমি বমি ভাব, কখনো জ্বর'),
  ('diarrhoea', 'causes', 0, 'Infections from unsafe food or water: viruses, bacteria and parasites', 'অনিরাপদ খাবার বা পানি থেকে সংক্রমণ: ভাইরাস, ব্যাকটেরিয়া ও পরজীবী'),
  ('diarrhoea', 'causes', 1, 'Some medicines, such as certain antibiotics, and food intolerance', 'কিছু ওষুধ, যেমন কিছু অ্যান্টিবায়োটিক, এবং খাবারে অসহিষ্ণুতা'),
  ('diarrhoea', 'causes', 2, 'Long-term bowel conditions if it keeps coming back', 'বারবার হলে পেটের দীর্ঘমেয়াদি অসুখ'),
  ('diarrhoea', 'see_doctor', 0, 'Diarrhoea for more than a week, or in a baby for more than a day', 'এক সপ্তাহের বেশি ডায়রিয়া, বা শিশুর এক দিনের বেশি'),
  ('diarrhoea', 'see_doctor', 1, 'Blood or black stools, or severe belly pain', 'রক্ত বা কালো পায়খানা, বা তীব্র পেটব্যথা'),
